function [VertexData,EdgeData,CellData,BoxSize,endPos,includeCell] = ReadSimulationOutput(fid, startPos)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Read from file given by id fid (generated by fopen) starting from position
% 'startPos' and collects relevant data for plotting/visualization.
% The file must be formatted according to Vertex Model
% input/output format.
% Reading will stop when keyword 'End' is encountered (even if there is
% more data following it). To read data beyond 'End', call the function
% again starting from 'endPos'.
% Output VertexData, EdgeData, and CellData are all struct with relevant
% data as fields, and BoxSize gives the size of the box (useful for
% plotting Periodic Boundary Condition). 'endPos' is the ending position
% (useful to read multiple configurations appended in one text file).
%
% Created by Jeremy Hadidjojo (hjeremy@umich.edu), 05/22/14
%
% Last modified on: 03/14/16
%
% List of changes:
%
% 06/08/14: Made compatible with reading multiple configurations appended
% in a single file. Now takes file ID 'fid' and 'startPos', and outputs 
% 'endPos', at first keyword 'End' encountered. (useful for multiple calls 
% to the function). Now fopen and fclose must be done manually outside this
% function.
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Pre{1,1} = NaN(25000,1);        %vector for preallocations


%bool variable to tell if _CWVertices is included. Drawing cells requires
%clockwise-ordered list of vertices. If _CWVertices is not found in the
%text file, includeCell will be 'false' and the rest of the code won't try
%to draw the cells.
includeCell = true;


%% Set starting position
fseek(fid, startPos, 'bof');


%% Read Box Size (for periodic boundary condition)
%Read and find 'LX' and 'LY' keywords until 'endGlobal'
line = fgetl(fid);

%return if end-of-file reached
if ~ischar(line)
    endPos = -2;
    VertexData = [];
    EdgeData = [];
    CellData = [];
    BoxSize = [];
    return
end
    
Lx = 0;
Ly = 0;
while ~strcmpi(line, 'endGlobal')
    if strncmpi(line, 'LX', 2)
        Lx = textscan(line, '%*s %f');
    elseif strncmpi(line, 'LY', 2)
        Ly = textscan(line, '%*s %f');
    end
    
    %return if end-of-file reached
    line = fgetl(fid);
    if ~ischar(line)
        endPos = -2;
        VertexData = [];
        EdgeData = [];
        CellData = [];
        BoxSize = [];
        return
    end
end

%Output Lx and Ly as BoxSize
BoxSize = [Lx{1},Ly{1}];


%Advance until keyword 'Vertices'
line = fgetl(fid);
while ~strcmpi(line, 'Vertices')
    line = fgetl(fid);
end


%% Read Vertex Data
%Read vertex field keywords
line = fgetl(fid);
VFields = textscan(line, '%s');
VFields = VFields{1}';

%Read vertex field data and store to temp var VData
line = fgetl(fid);
VData = [];
while ~strcmpi(line, 'Edges')       %Read until keyword 'Edges'
    tempdata = textscan(line, '%f');
    VData = [VData; tempdata{1}'];
    line = fgetl(fid);
end

%% Process Vertex Data
nFields = length(VFields);

%preallocate struc for outputting data
%VertexData = struct('id', Pre, 'x',Pre, 'y', Pre, 'Tx', Pre, 'Ty', Pre, 'Px', Pre, 'Py', Pre, 'EdgesNumber', Pre);
VertexData = struct('id', Pre, 'x', Pre, 'y', Pre, 'EdgesNumber', Pre, 'ForceX', Pre, 'ForceY', Pre);

%Extract vertex id, x, and y positions
for i = 1:nFields
    switch VFields{i}
        case 'id'
            VertexData(1).id = VData(:,i);
        case 'x'
            VertexData(1).x = VData(:,i);
        case 'y'
            VertexData(1).y = VData(:,i);
        case '_Ftension_x'
            VertexData(1).Tx = VData(:,i);
        case '_Ftension_y'
            VertexData(1).Ty = VData(:,i);
        case '_Fpressure_x'
            VertexData(1).Px = VData(:,i);
        case '_Fpressure_y'
            VertexData(1).Py = VData(:,i);
        case '_EdgesNumber'
            VertexData(1).EdgesNumber = VData(:,i);
        case 'ForceX'
            VertexData(1).ForceX = VData(:,i);
        case 'ForceY'
            VertexData(1).ForceY = VData(:,i);
        otherwise
            error('Invalid keyword in Vertices');
    end
end




%% Read Edge Data
%Read edges field keywords
line = fgetl(fid);
EFields = textscan(line, '%s');
EFields = EFields{1}';

%Read edge field data and store in temp var EData
line = fgetl(fid);
EData = [];
while ~strcmpi(line, 'Cells')       %Read until keyword 'Cells'
    tempdata = textscan(line, '%f');
    EData = [EData; tempdata{1}'];
    line = fgetl(fid);
end

%% Process Edge Data
nFields = length(EFields);

%preallocate struct for outputting data
%EdgeData = struct('id',Pre,'vertex1',Pre,'vertex2',Pre,'xflag',Pre,'yflag',Pre, ...
%    'length', Pre, 'tension', Pre, 'cell1', Pre, 'cell2', Pre);
EdgeData = struct('id', Pre, 'vertex1', Pre, 'vertex2', Pre, 'xflag', Pre, 'yflag', Pre, ...
    'tension', Pre, 'cell1', Pre, 'cell2', Pre);

%Extract edge id, vertex1, vertex2, xflag, and yflag.
for i = 1:nFields
    switch EFields{i}
        case 'id'
            EdgeData(1).id = EData(:,i);
        case 'vertex1'
            EdgeData(1).vertex1 = EData(:,i);
        case 'vertex2'
            EdgeData(1).vertex2 = EData(:,i);
        case 'xflag'
            EdgeData(1).xflag = EData(:,i);
        case 'yflag'
            EdgeData(1).yflag = EData(:,i);
        case '_length'
            EdgeData(1).length = EData(:,i);
        case '_Tension_x'
            EdgeData(1).Tx = EData(:,i);
        case '_Tension_y'
            EdgeData(1).Ty = EData(:,i);
        case '_cell1'
            EdgeData(1).cell1 = EData(:,i);
        case '_cell2'
            EdgeData(1).cell2 = EData(:,i);
        case 'tension'
            EdgeData(1).tension = EData(:,i);
        otherwise
            error(strcat('Invalid keyword in Edges: ', EFields{i}));
    end
end




%% Read Cell Data
%Read cells field keywords
line = fgetl(fid);
CFields = textscan(line, '%s');
CFields = CFields{1}';

%Read cell field data and store in temp var CData
line = fgetl(fid);
CData = [];
while ~strcmpi(line, 'End')             %Read until keyword 'End'
    tempdata = textscan(line, '%s');    %read as string (not float) to preserve EdgeList
    CData = [CData; tempdata{1}'];
    line = fgetl(fid);
end


%% Process Cell Data

nFields = length(CFields);
nCell = size(CData,1);

%preallocate struct for outputting data
%NOTE: unlike other fields, EdgeList is a cell not vector (since the list has variable
%length)
% for agperim model
CellData = struct('id', Pre,'EdgeNumb',Pre,'EdgeList',{}, 'Type', Pre, ...
    'CWVertices', Pre, 'A0', Pre,'P0', Pre, 'Area', Pre, 'Pressure', Pre, 'xflag', Pre, 'yflag', Pre, ...
    'Center_x', Pre, 'Center_y', Pre, 'dEnergy', Pre);
%for agcell model
%CellData = struct('id', Pre,'EdgeNumb',Pre,'EdgeList',{}, 'Type', Pre, ...
%    'CWVertices', Pre, 'A0', Pre, 'Area', Pre, 'Pressure', Pre, 'xflag', Pre, 'yflag', Pre, ...
%    'Center_x', Pre, 'Center_y', Pre, 'dEnergy', Pre);

%Extract edge id, EdgeNumb, and EdgeList.
for i = 1:nFields
    switch CFields{i}
        case 'id'
            CellData(1).id(:,1) = uint32( str2double(CData(:,i)) );
        case 'A0'
            CellData(1).A0(:,1) = str2double(CData(:,i));
        case 'EdgeNumb'
            CellData(1).EdgeNumb(:,1) = uint8( str2double(CData(:,i)) );
        case 'EdgeList'
            for j = 1:nCell
                CellData(1).EdgeList(j,1) = textscan(CData{j,i},'%d','Delimiter',',');
            end
        case 'Type'
            CellData(1).Type(:,1) = uint8( str2double(CData(:,i)) );
        case 'CWVertices'
            includeCell = true;
            for j = 1:nCell
                CellData(1).CWVertices(j,1) = textscan(CData{j,i},'%d','Delimiter',',');
            end
        case 'Area'
            CellData(1).Area(:,1) = str2double(CData(:,i));
        case 'Pressure'
            CellData(1).Pressure(:,1) = str2double(CData(:,i));
        case 'xflag'
            CellData(1).xflag(:,1) = logical( str2double(CData(:,i)) );
        case 'yflag'
            CellData(1).yflag(:,1) = logical( str2double(CData(:,i)) );
        case 'Centerx'
            CellData(1).Center_x(:,1) = str2double(CData(:,i));
        case 'Centery'
            CellData(1).Center_y(:,1) = str2double(CData(:,i));
        case 'dEnergy'
            CellData(1).dEnergy(:,1) = str2double(CData(:,i));
        case 'P0'
            CellData(1).P0(:,1) = str2double(CData(:,i));
        otherwise
            %error( ['Invalid keyword in Cells: ', CFields{i}] )
    end
end




endPos = ftell(fid);

